import React, { useState, useEffect, useCallback } from 'react';
import './WeatherMonitor.css';

// Coordinates for Quezon City, Philippines
const QC_LAT = 14.6760;
const QC_LON = 121.0437;

// WMO Weather Codes to Human-readable conditions and icons
const wmoCodeToCondition = (code) => {
  if (code === 0) return 'Clear Sky';
  if (code === 1) return 'Mainly Clear';
  if (code === 2) return 'Partly Cloudy';
  if (code === 3) return 'Overcast';
  if (code >= 45 && code <= 48) return 'Fog';
  if (code >= 51 && code <= 55) return 'Drizzle';
  if (code >= 56 && code <= 57) return 'Freezing Drizzle';
  if (code >= 61 && code <= 63) return 'Light Rain';
  if (code === 65) return 'Heavy Rain';
  if (code >= 66 && code <= 67) return 'Freezing Rain';
  if (code >= 71 && code <= 77) return 'Snow';
  if (code >= 80 && code <= 82) return 'Rain Showers';
  if (code >= 85 && code <= 86) return 'Snow Showers';
  if (code === 95) return 'Thunderstorm';
  if (code >= 96 && code <= 99) return 'Thunderstorm with Hail';
  return 'Partly Cloudy';
};

const wmoCodeToIcon = (code) => {
  if (code === 0) return '☀️';
  if (code === 1) return '🌤️';
  if (code === 2) return '⛅';
  if (code === 3) return '☁️';
  if (code >= 45 && code <= 48) return '🌫️';
  if (code >= 51 && code <= 57) return '🌦️';
  if (code >= 61 && code <= 63) return '🌦️';
  if (code === 65) return '🌧️';
  if (code >= 66 && code <= 67) return '🌧️';
  if (code >= 71 && code <= 77) return '❄️';
  if (code >= 80 && code <= 82) return '🌧️';
  if (code >= 85 && code <= 86) return '🌨️';
  if (code === 95) return '⛈️';
  if (code >= 96 && code <= 99) return '⛈️';
  return '🌤️';
};

const degreesToCompass = (deg) => {
  const dirs = ['N', 'NNE', 'NE', 'ENE', 'E', 'ESE', 'SE', 'SSE', 'S', 'SSW', 'SW', 'WSW', 'W', 'WNW', 'NW', 'NNW'];
  return dirs[Math.round(deg / 22.5) % 16];
};

const getUVInfo = (uv) => {
  if (uv >= 11) return { label: 'Extreme', color: '#a142f4', tip: 'Take full precautions; crops and workers need shade.' };
  if (uv >= 8) return { label: 'Very High', color: '#ea4335', tip: 'Very strong sun; protect sensitive nursery seedlings.' };
  if (uv >= 6) return { label: 'High', color: '#fbbc05', tip: 'Provide afternoon shade for young vegetable transplants.' };
  if (uv >= 3) return { label: 'Moderate', color: '#f9ab00', tip: 'Standard crop sunlight; good for photosynthesis.' };
  return { label: 'Low', color: '#34a853', tip: 'Minimal UV risk; ideal field working conditions.' };
};

// Generate smart agronomic advisories for Quezon City urban/rural farmers
const generateAgriculturalAlerts = (current, daily) => {
  const alerts = [];

  // Rain forecast check
  const heavyRainDays = daily.time
    .map((t, i) => ({
      day: new Date(t).toLocaleDateString('en-US', { weekday: 'long' }),
      rain: daily.precipitation_sum[i]
    }))
    .filter(d => d.rain >= 15);

  if (heavyRainDays.length > 0) {
    alerts.push({
      type: 'warning',
      title: 'Heavy Rainfall Warning',
      message: `Expected ${heavyRainDays[0].rain} mm on ${heavyRainDays[0].day}. Clear farm drainage channels, inspect raised beds, and protect vulnerable short-cycle leafy greens.`
    });
  }

  // Dry spell opportunity
  const dryDays = daily.precipitation_sum.filter(r => r < 1.0).length;
  if (dryDays >= 3) {
    alerts.push({
      type: 'success',
      title: 'Favorable Spraying & Fieldwork Window',
      message: `${dryDays} dry days forecast ahead. Excellent window for weeding, organic pesticide application, and soil preparation.`
    });
  }

  // Humidity & disease risk
  if (current.relative_humidity_2m >= 85) {
    alerts.push({
      type: 'info',
      title: 'High Humidity Disease Watch',
      message: `High relative humidity (${current.relative_humidity_2m}%). Watch for bacterial wilt and downy mildew in tomatoes, eggplants, and pechay.`
    });
  }

  // High UV warning
  const todayUV = daily.uv_index_max[0];
  if (todayUV >= 8) {
    alerts.push({
      type: 'warning',
      title: 'High Solar Heat / UV Index',
      message: `UV index peak reaching ${todayUV.toFixed(1)}. Maintain mulch to retain soil moisture and avoid transplanting during peak midday heat.`
    });
  }

  if (alerts.length === 0) {
    alerts.push({
      type: 'info',
      title: 'Normal Growing Conditions',
      message: 'Weather parameters are within optimal ranges for short-cycle crop cultivation in Quezon City.'
    });
  }

  return alerts;
};

export default function WeatherMonitor() {
  const [weatherData, setWeatherData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [lastUpdated, setLastUpdated] = useState(null);
  const [unit, setUnit] = useState('C'); // 'C' or 'F'
  const [hourlyTab, setHourlyTab] = useState('temp'); // 'temp', 'precip', 'wind'

  // Zoom Earth / Satellite widget settings
  const [zoomSize, setZoomSize] = useState('small'); // 'small' (default compact) or 'large'
  const [zoomMinimized, setZoomMinimized] = useState(false); // minimizable toggle
  const [zoomLayer, setZoomLayer] = useState('radar'); // 'radar', 'satellite', 'wind'

  // Fetch Weather Data from Open-Meteo
  const fetchWeatherData = useCallback(async () => {
    setLoading(true);
    try {
      const params = new URLSearchParams({
        latitude: QC_LAT,
        longitude: QC_LON,
        current: 'temperature_2m,relative_humidity_2m,apparent_temperature,precipitation,weather_code,wind_speed_10m,wind_direction_10m,surface_pressure,cloud_cover',
        hourly: 'temperature_2m,precipitation_probability,precipitation,weather_code,wind_speed_10m',
        daily: 'weather_code,temperature_2m_max,temperature_2m_min,apparent_temperature_max,precipitation_sum,precipitation_probability_max,wind_speed_10m_max,uv_index_max,sunrise,sunset',
        timezone: 'Asia/Manila',
        forecast_days: 7
      });

      const res = await fetch(`https://api.open-meteo.com/v1/forecast?${params}`);
      if (!res.ok) throw new Error(`Weather fetch failed: ${res.status}`);
      const data = await res.json();

      const cur = data.current;
      const d = data.daily;
      const h = data.hourly;

      // Slice next 24 hours of hourly data starting from current time
      const currentIsoHour = cur.time ? cur.time.slice(0, 13) : '';
      let startHourIdx = h.time.findIndex(t => t.startsWith(currentIsoHour));
      if (startHourIdx === -1) startHourIdx = 0;

      const hourlyList = [];
      for (let i = startHourIdx; i < Math.min(startHourIdx + 24, h.time.length); i++) {
        const timeStr = h.time[i];
        const dateObj = new Date(timeStr);
        const hour12 = dateObj.toLocaleTimeString('en-US', { hour: 'numeric', hour12: true });
        hourlyList.push({
          timeLabel: i === startHourIdx ? 'Now' : hour12,
          temp: Math.round(h.temperature_2m[i]),
          pop: h.precipitation_probability[i] || 0,
          precip: h.precipitation[i] || 0,
          weatherCode: h.weather_code[i],
          wind: Math.round(h.wind_speed_10m[i])
        });
      }

      // 7-day daily forecast
      const forecastDays = d.time.map((t, i) => {
        const dateObj = new Date(t);
        let dayName = dateObj.toLocaleDateString('en-US', { weekday: 'short' });
        if (i === 0) dayName = 'Today';
        if (i === 1) dayName = 'Tomorrow';

        return {
          date: t,
          day: dayName,
          minTemp: Math.round(d.temperature_2m_min[i]),
          maxTemp: Math.round(d.temperature_2m_max[i]),
          condition: wmoCodeToCondition(d.weather_code[i]),
          icon: wmoCodeToIcon(d.weather_code[i]),
          rainProb: d.precipitation_probability_max[i] || 0,
          rainSum: d.precipitation_sum[i] || 0,
          windMax: Math.round(d.wind_speed_10m_max[i]),
          uvMax: d.uv_index_max[i],
          sunrise: d.sunrise[i] ? d.sunrise[i].split('T')[1] : '05:44',
          sunset: d.sunset[i] ? d.sunset[i].split('T')[1] : '18:03'
        };
      });

      setWeatherData({
        current: {
          temp: Math.round(cur.temperature_2m),
          feelsLike: Math.round(cur.apparent_temperature),
          humidity: cur.relative_humidity_2m,
          precipitation: cur.precipitation,
          weatherCode: cur.weather_code,
          condition: wmoCodeToCondition(cur.weather_code),
          icon: wmoCodeToIcon(cur.weather_code),
          windSpeed: Math.round(cur.wind_speed_10m),
          windDirection: degreesToCompass(cur.wind_direction_10m),
          pressure: Math.round(cur.surface_pressure),
          cloudCover: cur.cloud_cover,
          uvIndex: d.uv_index_max[0] || 6,
          sunrise: d.sunrise[0] ? new Date(d.sunrise[0]).toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' }) : '5:44 AM',
          sunset: d.sunset[0] ? new Date(d.sunset[0]).toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' }) : '6:03 PM'
        },
        hourly: hourlyList,
        forecast: forecastDays,
        alerts: generateAgriculturalAlerts(cur, d)
      });

      setLastUpdated(new Date());
    } catch (err) {
      console.error('Weather fetching error:', err);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchWeatherData();
    const interval = setInterval(fetchWeatherData, 10 * 60 * 1000); // 10 minutes auto-sync
    return () => clearInterval(interval);
  }, [fetchWeatherData]);

  // Convert temperature helper based on active unit
  const formatTemp = (celsius) => {
    if (unit === 'F') {
      return `${Math.round((celsius * 9) / 5 + 32)}°`;
    }
    return `${celsius}°`;
  };

  // Build Windy / Satellite iframe URL
  const getEmbedUrl = () => {
    const base = 'https://embed.windy.com/embed.html?type=map&location=coordinates&metricRain=mm&metricTemp=°C&metricWind=km/h&lat=14.676&lon=121.044&detailLat=14.676&detailLon=121.044&marker=true&message=true';
    if (zoomLayer === 'satellite') {
      return `${base}&zoom=9&overlay=satellite&product=satellite&level=surface`;
    }
    if (zoomLayer === 'wind') {
      return `${base}&zoom=10&overlay=wind&product=ecmwf&level=surface`;
    }
    // Default: radar
    return `${base}&zoom=10&overlay=radar&product=radar&level=surface`;
  };

  if (loading && !weatherData) {
    return (
      <div className="gw-loading">
        <div className="gw-loading-icon">🌤️</div>
        <h2>Loading Quezon City Weather...</h2>
        <p style={{ color: '#5f6368', marginTop: '6px' }}>Fetching real-time meteorological observations</p>
      </div>
    );
  }

  if (!weatherData) {
    return (
      <div className="gw-error">
        <div className="gw-error-icon">⚠️</div>
        <h2>Unable to Load Weather Data</h2>
        <p style={{ color: '#5f6368' }}>Please check your network connection and try again.</p>
        <button className="gw-btn-retry" onClick={fetchWeatherData}>
          🔄 Try Again
        </button>
      </div>
    );
  }

  const { current, hourly, forecast, alerts } = weatherData;
  const uvInfo = getUVInfo(current.uvIndex);

  // Weekly min and max for Google-style temperature range slider bar
  const weekMin = Math.min(...forecast.map(f => f.minTemp));
  const weekMax = Math.max(...forecast.map(f => f.maxTemp));

  return (
    <div className="gw-container">
      {/* 1. Header Bar: Location, Time, Unit Toggle & Sync */}
      <div className="gw-header-bar">
        <div className="gw-header-left">
          <div className="gw-location-title">
            <span className="gw-location-pin">📍</span>
            <span>Quezon City, Metro Manila</span>
            <span className="gw-live-badge">
              <span className="gw-live-dot"></span>
              LIVE
            </span>
          </div>
          <div className="gw-subtitle">
            Weather • {new Date().toLocaleDateString('en-US', { weekday: 'long', month: 'short', day: 'numeric' })}
            {lastUpdated && ` • Updated ${lastUpdated.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' })}`}
          </div>
        </div>

        <div className="gw-header-right">
          {/* Temperature Unit Switcher: °C | °F */}
          <div className="gw-unit-toggle">
            <button
              className={`gw-unit-btn ${unit === 'C' ? 'active' : ''}`}
              onClick={() => setUnit('C')}
            >
              °C
            </button>
            <button
              className={`gw-unit-btn ${unit === 'F' ? 'active' : ''}`}
              onClick={() => setUnit('F')}
            >
              °F
            </button>
          </div>

          {/* Sync Button */}
          <button
            className="gw-btn-action"
            onClick={fetchWeatherData}
            disabled={loading}
            title="Refresh Live Weather"
          >
            <span>{loading ? '⏳' : '🔄'}</span>
            <span>Sync</span>
          </button>
        </div>
      </div>

      {/* 2. ZOOM EARTH FEATURE (Kept Small by default, Minimizable & Expandable with Toggle Button) */}
      {zoomMinimized ? (
        <div className="gw-ze-minimized">
          <div style={{ display: 'flex', alignItems: 'center', gap: '8px', fontSize: '0.86rem', fontWeight: 600 }}>
            <span>🛰️</span>
            <span>Zoom Earth / Live Weather Radar (Quezon City)</span>
            <span style={{ color: '#64748b', fontSize: '0.75rem', fontWeight: 'normal' }}>— Minimized</span>
          </div>
          <div style={{ display: 'flex', gap: '8px' }}>
            <button
              className="gw-ze-btn gw-ze-btn-primary"
              onClick={() => setZoomMinimized(false)}
            >
              ➕ Show Radar Map
            </button>
            <a
              href="https://zoom.earth/places/philippines/quezon-city/"
              target="_blank"
              rel="noreferrer"
              className="gw-ze-btn"
              style={{ textDecoration: 'none' }}
            >
              Zoom Earth ↗
            </a>
          </div>
        </div>
      ) : (
        <div className="gw-zoom-earth-card">
          <div className="gw-ze-header">
            <div className="gw-ze-title">
              <span>🛰️</span>
              <span>Zoom Earth / Live Radar</span>
              <span className="gw-ze-badge">Quezon City 14.68°N, 121.04°E</span>
            </div>

            <div className="gw-ze-actions">
              {/* Layer switch */}
              <div className="gw-ze-tabs">
                <button
                  className={`gw-ze-tab ${zoomLayer === 'radar' ? 'active' : ''}`}
                  onClick={() => setZoomLayer('radar')}
                >
                  🌧️ Radar
                </button>
                <button
                  className={`gw-ze-tab ${zoomLayer === 'satellite' ? 'active' : ''}`}
                  onClick={() => setZoomLayer('satellite')}
                >
                  🛰️ Satellite
                </button>
                <button
                  className={`gw-ze-tab ${zoomLayer === 'wind' ? 'active' : ''}`}
                  onClick={() => setZoomLayer('wind')}
                >
                  💨 Wind
                </button>
              </div>

              {/* Toggle Size Button: Small / Large (Expandable) */}
              <button
                className="gw-ze-btn gw-ze-btn-primary"
                onClick={() => setZoomSize(zoomSize === 'small' ? 'large' : 'small')}
                title={zoomSize === 'small' ? 'Expand Radar Map to Large' : 'Shrink Radar Map to Small'}
              >
                {zoomSize === 'small' ? '⤢ Expand (Large)' : '⤡ Shrink (Small)'}
              </button>

              {/* Minimizable Button */}
              <button
                className="gw-ze-btn"
                onClick={() => setZoomMinimized(true)}
                title="Minimize Radar Map"
              >
                ➖ Minimize
              </button>
            </div>
          </div>

          {/* Iframe Body: Small height (240px) or Large height (520px) */}
          <div className={`gw-ze-body size-${zoomSize}`}>
            <iframe
              title="Quezon City Zoom Earth & Weather Radar"
              src={getEmbedUrl()}
              loading="lazy"
            />
          </div>

          <div className="gw-ze-footer">
            <span>Live Satellite & Doppler Radar Feed</span>
            <div style={{ display: 'flex', gap: '12px' }}>
              <span>Mode: <strong style={{ color: '#93c5fd' }}>{zoomSize.toUpperCase()}</strong></span>
              <a
                href="https://zoom.earth/places/philippines/quezon-city/"
                target="_blank"
                rel="noreferrer"
                className="gw-ze-link"
              >
                Open in Zoom Earth ↗
              </a>
            </div>
          </div>
        </div>
      )}

      {/* 3. GOOGLE WEATHER HERO CARD */}
      <div className="gw-hero-card">
        <div className="gw-hero-main">
          {/* Left: Huge Temp + Icon + Condition */}
          <div className="gw-hero-left">
            <div className="gw-hero-icon-wrapper">{current.icon}</div>
            <div className="gw-hero-temp-block">
              <div className="gw-hero-temp">{formatTemp(current.temp)}</div>
              <div className="gw-hero-condition">{current.condition}</div>
              <div className="gw-hero-feels">Feels like {formatTemp(current.feelsLike)}</div>
            </div>
          </div>

          {/* Right: Google Weather 3 Key Pillars */}
          <div className="gw-hero-right">
            <div className="gw-hero-stat-row">
              <span className="gw-stat-label">
                <span>💧</span> Precipitation:
              </span>
              <span className="gw-stat-value">{current.precipitation} mm ({hourly[0]?.pop || 0}%)</span>
            </div>

            <div className="gw-hero-stat-row">
              <span className="gw-stat-label">
                <span>💦</span> Humidity:
              </span>
              <span className="gw-stat-value">{current.humidity}%</span>
            </div>

            <div className="gw-hero-stat-row">
              <span className="gw-stat-label">
                <span>💨</span> Wind:
              </span>
              <span className="gw-stat-value">{current.windSpeed} km/h {current.windDirection}</span>
            </div>
          </div>
        </div>
      </div>

      {/* 4. HOURLY FORECAST (Signature Google Tabs: Temperature, Precipitation, Wind) */}
      <div className="gw-hourly-section">
        <div className="gw-hourly-header">
          <div className="gw-hourly-title">Hourly Forecast (Next 24 Hours)</div>
          <div className="gw-tabs">
            <button
              className={`gw-tab-btn ${hourlyTab === 'temp' ? 'active' : ''}`}
              onClick={() => setHourlyTab('temp')}
            >
              Temperature
            </button>
            <button
              className={`gw-tab-btn ${hourlyTab === 'precip' ? 'active' : ''}`}
              onClick={() => setHourlyTab('precip')}
            >
              Precipitation
            </button>
            <button
              className={`gw-tab-btn ${hourlyTab === 'wind' ? 'active' : ''}`}
              onClick={() => setHourlyTab('wind')}
            >
              Wind
            </button>
          </div>
        </div>

        {/* Scrollable Hourly Strip */}
        <div className="gw-hourly-scroll">
          {hourly.map((item, idx) => (
            <div key={idx} className={`gw-hourly-item ${idx === 0 ? 'now' : ''}`}>
              <div className="gw-hourly-time">{item.timeLabel}</div>
              <div className="gw-hourly-icon">{wmoCodeToIcon(item.weatherCode)}</div>

              {hourlyTab === 'temp' && (
                <div className="gw-hourly-val">{formatTemp(item.temp)}</div>
              )}

              {hourlyTab === 'precip' && (
                <>
                  <div className="gw-hourly-val" style={{ color: '#1a73e8', fontSize: '0.84rem' }}>
                    {item.pop}%
                  </div>
                  <div className="gw-hourly-bar-container">
                    <div
                      className="gw-hourly-bar-fill"
                      style={{ height: `${Math.max(item.pop * 0.22, 3)}px` }}
                    />
                  </div>
                </>
              )}

              {hourlyTab === 'wind' && (
                <div className="gw-hourly-val" style={{ fontSize: '0.82rem', color: '#3c4043' }}>
                  {item.wind} km/h
                </div>
              )}
            </div>
          ))}
        </div>
      </div>

      {/* 5. 7-DAY FORECAST WITH GOOGLE WEATHER RANGE SLIDERS */}
      <div className="gw-7day-section">
        <div className="gw-7day-title">7-Day Weather Forecast</div>
        <div className="gw-7day-list">
          {forecast.map((day, idx) => {
            // Calculate position for Google-style temperature bar
            const rangeSpan = Math.max(weekMax - weekMin, 1);
            const leftPct = ((day.minTemp - weekMin) / rangeSpan) * 100;
            const widthPct = Math.max(((day.maxTemp - day.minTemp) / rangeSpan) * 100, 8);

            return (
              <div key={idx} className="gw-7day-row">
                <div className="gw-7day-day">{day.day}</div>

                <div className="gw-7day-pop">
                  {day.rainProb > 0 ? (
                    <>
                      <span>💧</span>
                      <span>{day.rainProb}%</span>
                    </>
                  ) : (
                    <span style={{ color: '#9aa0a6' }}>—</span>
                  )}
                </div>

                <div className="gw-7day-condition">
                  <span style={{ fontSize: '1.2rem' }}>{day.icon}</span>
                  <span>{day.condition}</span>
                </div>

                <div className="gw-7day-range-wrapper">
                  <span className="gw-temp-low">{formatTemp(day.minTemp)}</span>
                  <div className="gw-range-bar-track">
                    <div
                      className="gw-range-bar-fill"
                      style={{
                        left: `${leftPct}%`,
                        width: `${widthPct}%`
                      }}
                    />
                  </div>
                  <span className="gw-temp-high">{formatTemp(day.maxTemp)}</span>
                </div>
              </div>
            );
          })}
        </div>
      </div>

      {/* 6. WEATHER DETAILS CARDS GRID (Google Weather Cards) */}
      <div className="gw-details-grid">
        {/* UV Index Card */}
        <div className="gw-detail-card">
          <div className="gw-dc-header">
            <span>☀️</span>
            <span>UV Index</span>
          </div>
          <div className="gw-dc-val-main" style={{ color: uvInfo.color }}>
            {current.uvIndex.toFixed(1)} <span style={{ fontSize: '1rem', fontWeight: 600 }}>({uvInfo.label})</span>
          </div>
          <div className="gw-uv-bar" />
          <div className="gw-dc-sub">{uvInfo.tip}</div>
        </div>

        {/* Sunrise & Sunset Card */}
        <div className="gw-detail-card">
          <div className="gw-dc-header">
            <span>🌅</span>
            <span>Sunrise & Sunset</span>
          </div>
          <div className="gw-sun-arc-box">
            <div className="gw-sun-times">
              <span>🌅 {current.sunrise}</span>
              <span>🌇 {current.sunset}</span>
            </div>
            <div className="gw-sun-progress">
              <div className="gw-sun-progress-fill" style={{ width: '65%' }} />
            </div>
          </div>
          <div className="gw-dc-sub">Daylight Duration: ~12 hours 19 mins</div>
        </div>

        {/* Wind & Gusts Card */}
        <div className="gw-detail-card">
          <div className="gw-dc-header">
            <span>💨</span>
            <span>Wind & Gusts</span>
          </div>
          <div className="gw-dc-val-main">{current.windSpeed} <span style={{ fontSize: '1rem' }}>km/h</span></div>
          <div className="gw-dc-sub">Direction: {current.windDirection} • Max daily gusts: ~{forecast[0]?.windMax || 15} km/h</div>
        </div>

        {/* Humidity & Dew Point Card */}
        <div className="gw-detail-card">
          <div className="gw-dc-header">
            <span>💧</span>
            <span>Humidity</span>
          </div>
          <div className="gw-dc-val-main">{current.humidity}%</div>
          <div className="gw-dc-sub">Dew point is {formatTemp(Math.round(current.temp - ((100 - current.humidity) / 5)))} right now</div>
        </div>

        {/* Air Pressure Card */}
        <div className="gw-detail-card">
          <div className="gw-dc-header">
            <span>📊</span>
            <span>Pressure</span>
          </div>
          <div className="gw-dc-val-main">{current.pressure} <span style={{ fontSize: '1rem' }}>hPa</span></div>
          <div className="gw-dc-sub">Surface atmospheric barometric pressure</div>
        </div>

        {/* Cloud Cover Card */}
        <div className="gw-detail-card">
          <div className="gw-dc-header">
            <span>☁️</span>
            <span>Cloud Cover</span>
          </div>
          <div className="gw-dc-val-main">{current.cloudCover != null ? `${current.cloudCover}%` : 'N/A'}</div>
          <div className="gw-dc-sub">{current.cloudCover > 75 ? 'Heavy cloud coverage' : current.cloudCover > 30 ? 'Partly cloudy sky' : 'Clear skies'}</div>
        </div>
      </div>

      {/* 7. AGRICULTURAL ADVISORIES (Tailored for Farmers) */}
      <div className="gw-agro-card">
        <div className="gw-agro-title">
          <span>🌾</span>
          <span>ClimaYield Agricultural Weather Advisories (Quezon City)</span>
        </div>
        <div className="gw-agro-alerts">
          {alerts.map((alert, idx) => (
            <div key={idx} className={`gw-alert-item gw-alert-${alert.type}`}>
              <div style={{ fontSize: '1.2rem', marginTop: '1px' }}>
                {alert.type === 'warning' ? '⚠️' : alert.type === 'success' ? '✅' : 'ℹ️'}
              </div>
              <div>
                <strong style={{ display: 'block', marginBottom: '2px', color: '#202124' }}>
                  {alert.title}
                </strong>
                <span>{alert.message}</span>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
